/**
 * Capability system for adapter feature detection
 */

import type { TransactionIsolation } from './types.js';

export interface AdapterCapabilities {
  // Supported data types
  types: {
    json: boolean;
    dates: boolean;
    booleans: boolean;
    bigint: boolean;
    uuid: boolean;
    enum: boolean;
  };

  // Supported operations
  operations: {
    batch: boolean; // createMany, updateMany, deleteMany
    upsert: boolean; // Upsert operation
    streaming: boolean; // Stream large datasets
    fulltext: boolean; // Full-text search
    returning: boolean; // RETURNING clause support
    strictUpdateNotFound?: boolean; // update() throws NotFoundError/canonical not-found on zero matched rows
  };

  // Transaction support
  transactions: {
    supported: boolean;
    nested: boolean; // Savepoints
    isolation?: TransactionIsolation[];
    /** Honors explicit per-call transaction isolation options. */
    configurableIsolation?: boolean;
  };

  // Performance characteristics
  performance: {
    maxBatchSize?: number;
    supportsJoins: boolean;
    supportsPreparedStatements: boolean;
  };

  // Schema capabilities
  schema: {
    migrations: boolean;
    constraints: boolean;
    indexes: boolean;
  };

  // Advanced features
  advanced: {
    customIdGeneration: boolean;
    numericIds: boolean;
    schemaNamespaces: boolean;
    customTypes: boolean;
  };
}

/**
 * Default capabilities - conservative defaults that work everywhere
 */
export const DEFAULT_CAPABILITIES: AdapterCapabilities = {
  types: {
    json: false,
    dates: true,
    booleans: true,
    bigint: false,
    uuid: false,
    enum: false,
  },
  operations: {
    batch: false,
    upsert: false,
    streaming: false,
    fulltext: false,
    returning: false,
    strictUpdateNotFound: false,
  },
  transactions: {
    supported: false,
    nested: false,
  },
  performance: {
    supportsJoins: false,
    supportsPreparedStatements: false,
  },
  schema: {
    migrations: false,
    constraints: false,
    indexes: false,
  },
  advanced: {
    customIdGeneration: false,
    numericIds: false,
    schemaNamespaces: false,
    customTypes: false,
  },
};

/**
 * Merge partial capabilities with defaults
 */
export function mergeCapabilities(
  partial: Partial<AdapterCapabilities>
): AdapterCapabilities {
  return {
    types: { ...DEFAULT_CAPABILITIES.types, ...partial.types },
    operations: { ...DEFAULT_CAPABILITIES.operations, ...partial.operations },
    transactions: { ...DEFAULT_CAPABILITIES.transactions, ...partial.transactions },
    performance: { ...DEFAULT_CAPABILITIES.performance, ...partial.performance },
    schema: { ...DEFAULT_CAPABILITIES.schema, ...partial.schema },
    advanced: { ...DEFAULT_CAPABILITIES.advanced, ...partial.advanced },
  };
}
/**
 * Core type definitions for the adapter system
 */

import type { AdapterCapabilities } from './capabilities.js';

// ============================================================================
// Adapter Interface
// ============================================================================

export interface Adapter {
  // Metadata
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly capabilities: AdapterCapabilities;

  // Core CRUD operations
  create<T = any>(params: CreateParams): Promise<T>;
  findOne<T = any>(params: FindOneParams): Promise<T | null>;
  findMany<T = any>(params: FindManyParams): Promise<T[]>;
  update<T = any>(params: UpdateParams): Promise<T>;
  delete(params: DeleteParams): Promise<void>;

  // Batch operations
  createMany<T = any>(params: CreateManyParams): Promise<T[]>;
  updateMany(params: UpdateManyParams): Promise<number>;
  deleteMany(params: DeleteManyParams): Promise<number>;

  // Advanced operations
  upsert<T = any>(params: UpsertParams): Promise<T>;
  count(params: CountParams): Promise<number>;

  // Transaction support
  transaction<R>(callback: (trx: TransactionAdapter) => Promise<R>, options?: { isolationLevel: TransactionIsolation }): Promise<R>;

  // Lifecycle management
  initialize(): Promise<void>;
  isHealthy(): Promise<HealthStatus>;
  close(): Promise<void>;

  // Schema management
  getSchemaVersion(namespace: string): Promise<number>;
  setSchemaVersion(namespace: string, version: number): Promise<void>;
  validateSchema(schema: TableSchema): Promise<ValidationResult>;

  // Optional: Schema generation for CLI
  createSchema?(params: CreateSchemaParams): Promise<SchemaCreation>;

  /** Raw CRUD for internal tables, bypasses ORM schema resolution */
  readonly internal: InternalCrud;
}

export interface TransactionAdapter extends Omit<Adapter, 'transaction' | 'close'> {
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface HealthStatus {
  healthy: boolean;
  connections?: {
    active: number;
    idle: number;
    max: number;
  };
  lastError?: Error;
  uptime: number;
}

// ============================================================================
// Operation Parameters
// ============================================================================

export interface CreateParams {
  model: string; // Table name
  data: Record<string, any>; // Data to insert
  select?: string[]; // Fields to return
  namespace?: string; // Library namespace
}

export interface FindOneParams {
  model: string;
  where: WhereClause[];
  select?: string[];
  join?: JoinConfig;
  namespace?: string;
}

export interface FindManyParams extends FindOneParams {
  limit?: number;
  offset?: number;
  orderBy?: OrderBy[];
}

export interface UpdateParams {
  model: string;
  where: WhereClause[];
  data: Record<string, any>;
  select?: string[];
  namespace?: string;
}

export interface DeleteParams {
  model: string;
  where: WhereClause[];
  namespace?: string;
}

export interface CreateManyParams {
  model: string;
  data: Record<string, any>[];
  select?: string[];
  namespace?: string;
}

export interface UpdateManyParams {
  model: string;
  where: WhereClause[];
  data: Record<string, any>;
  namespace?: string;
}

export interface DeleteManyParams {
  model: string;
  where: WhereClause[];
  namespace?: string;
}

export interface UpsertParams {
  model: string;
  where: WhereClause[];
  create: Record<string, any>;
  update: Record<string, any>;
  select?: string[];
  namespace?: string;
  /** Explicit ON CONFLICT target column(s). When set, overrides columns derived from `where`. */
  conflictTarget?: string | string[];
}

export interface CountParams {
  model: string;
  where?: WhereClause[];
  namespace?: string;
}

// ============================================================================
// Query Building Types
// ============================================================================

export interface WhereClause {
  field: string;
  operator:
    | 'eq'
    | 'ne'
    | 'gt'
    | 'gte'
    | 'lt'
    | 'lte'
    | 'in'
    | 'not_in'
    | 'contains'
    | 'starts_with'
    | 'ends_with';
  value: any;
  connector?: 'AND' | 'OR';
}

export interface OrderBy {
  field: string;
  direction: 'asc' | 'desc';
}

export interface JoinConfig {
  model: string;
  on: {
    field: string;
    foreignField: string;
  };
  type?: 'inner' | 'left' | 'right';
}

// ============================================================================
// Schema Types
// ============================================================================

export interface TableSchema {
  modelName: string;
  fields: Record<string, FieldSchema>;
  indexes?: IndexSchema[];
  constraints?: ConstraintSchema[];
}

export type DateFieldValueType = 'date' | 'iso-string' | 'epoch-ms';

export type DateFieldStorageType =
  | 'timestamp'
  | 'timestamptz'
  | 'iso-text'
  | 'epoch-ms-integer'
  | 'epoch-ms-bigint';

export interface FieldSchema {
  type: 'string' | 'number' | 'boolean' | 'date' | 'datetime' | 'json' | 'bigint';
  required?: boolean;
  unique?: boolean;
  /** Maximum stored string length. MySQL migrations emit VARCHAR(length). */
  maxLength?: number;
  defaultValue?: any;
  /**
