  async updateSecretSet(id: string, input: UpdateSecretSetInput): Promise<SecretSetRecord> {
    const existing = await this.getSecretSet(id);
    const data: Partial<SecretSetRecord> = { updatedAt: nowIso() };
    if (input.name !== undefined) {
      const name = input.name.trim();
      if (!name) throw new SecFnValidationError("Secret set name is required");
      if (name !== existing.name) {
        const duplicate = await this.db.findOne<SecretSetRecord>({
          model: "secfn_secret_sets",
          where: [...scopeWhere({ tenantId: existing.tenantId, namespaceId: existing.namespaceId, name }), { field: "environmentId", operator: "eq", value: existing.environmentId ?? null }],
        });
        if (duplicate && duplicate.id !== id) throw new SecFnValidationError("Secret set already exists", { name });
        data.name = name;
      }
    }
    if (input.description !== undefined) data.description = input.description ?? undefined;
    const saved = Object.keys(data).length === 1
      ? existing
      : await this.db.update<SecretSetRecord>({
        model: "secfn_secret_sets",
        where: [{ field: "id", operator: "eq", value: id }],
        data: data as Record<string, unknown>,
      });
    await this.audit.write({
      type: "secret_accessed",
      severity: "info",
      tenantId: existing.tenantId,
      namespaceId: existing.namespaceId,
      namespace: existing.namespace,
      actorId: input.actorId,
      resource: `secret-set:${existing.name}`,
      action: "update",
      metadata: { setId: id, renamedTo: data.name },
    });
    return this.hydrateSet(saved);
  }

  private async withSetLock<T>(setId: string, operation: (vault: VaultService) => Promise<T>): Promise<T> {
    if (!this.db.capabilities.transactions.configurableIsolation || !this.db.capabilities.transactions.isolation?.includes("read_committed")) throw new SecFnValidationError("Secret set mutation requires read_committed transaction support");
    return this.db.transaction(async trx => {
      // Updating the parent takes a database row lock shared by all member writers.
      await trx.update({ model: "secfn_secret_sets", where: [{ field: "id", operator: "eq", value: setId }], data: { updatedAt: nowIso() } });
      const scopedDb: Adapter = { ...trx, transaction: async () => { throw new SecFnValidationError("Nested secret-set transactions are not supported"); }, close: async () => {} };
      return operation(new VaultService(scopedDb, this.keyProvider, this.audit));
    }, { isolationLevel: "read_committed" });
  }

