    this.assertSetMemberScope(set, secret);
    await this.assertUniqueSetOutputName(setId, { secretId, alias }, secret);
    const member: SecretSetMemberRecord = {
      id: generateId("member"),
      setId,
      secretId,
      alias: cleanString(alias),
      createdAt: nowIso(),
