        data.name = name;
      }
    }
    if (input.description !== undefined) data.description = input.description ?? undefined;
    const saved = Object.keys(data).length === 1
      ? existing
      : await this.db.update<SecretSetRecord>({
        model: "secfn_secret_sets",
