  }

  private async addSecretSetMemberLocked(setId: string, secretId: string, alias?: string): Promise<SecretSetMemberRecord> {
    const [set, secret] = await Promise.all([
      this.getSecretSetRow(setId),
      this.getSecretRow(secretId),
    ]);
    if (secret.namespaceId !== set.namespaceId) {
      throw new SecFnValidationError("Secret set members must belong to the same namespace", { setId, secretId });
    }
    this.assertSetMemberScope(set, secret);
    await this.assertUniqueSetOutputName(setId, { secretId, alias }, secret);
    const member: SecretSetMemberRecord = {
      id: generateId("member"),
      setId,
      secretId,
      alias: cleanString(alias),
      createdAt: nowIso(),
    };
    await this.db.create({ model: "secfn_secret_set_members", data: member as unknown as Record<string, unknown> });
    return member;
  }

  async listSecretSetMembers(setId: string): Promise<SecretSetMemberRecord[]> {
    await this.getSecretSetRow(setId);
    const members: SecretSetMemberRecord[] = [];
    let afterId: string | undefined;
    while (true) {
      const page = await this.db.findMany<SecretSetMemberRecord>({
        model: "secfn_secret_set_members",
        where: [{ field: "setId", operator: "eq", value: setId }, ...(afterId ? [{ field: "id", operator: "gt" as const, value: afterId }] : [])],
        orderBy: [{ field: "id", direction: "asc" }],
        limit: 1000,
      });
      members.push(...page);
      if (page.length < 1000) break;
      afterId = page[page.length - 1].id;
    }
    return members.sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id));
  }

  async updateSecretSetMember(id: string, input: UpdateSecretSetMemberInput): Promise<SecretSetMemberRecord> {
    const member = await this.db.findOne<SecretSetMemberRecord>({ model: "secfn_secret_set_members", where: [{ field: "id", operator: "eq", value: id }] });
    if (!member) throw new SecFnNotFoundError("Secret set member not found", { id });
    return this.withSetLock(member.setId, vault => vault.updateSecretSetMemberLocked(id, input));
  }

  private async updateSecretSetMemberLocked(id: string, input: UpdateSecretSetMemberInput): Promise<SecretSetMemberRecord> {
    const existing = await this.db.findOne<SecretSetMemberRecord>({
      model: "secfn_secret_set_members",
      where: [{ field: "id", operator: "eq", value: id }],
